_PREMIUM_INFO_27 = {
    "ru": "⭐️ <b>Больше возможностей с Premium</b>\n\nPremium превращает DealDock в полноценный инструмент анализа цен: помогает быстрее замечать интересные предложения и видеть больше информации о каждой игре.\n\n📊 <b>Расширенная аналитика цен</b>\n\n• текущая, минимальная и максимальная цена за период\n• средняя стоимость и изменения между проверками\n• оценка выгодности покупки\n• разница между текущей ценой и минимумом\n• подробная история изменения стоимости\n\n🏆 <b>Минимумы и выгодные предложения</b>\n\nСледите за новыми минимумами, повторным достижением лучшей цены и действительно интересными моментами для покупки.\n\n🌍 <b>Сравнение региональных цен</b>\n\nВыберите нужные регионы, сравните стоимость игры и приведите цены к одной валюте, чтобы быстрее увидеть наиболее выгодный вариант.\n\n⚡️ <b>Более частые проверки</b>\n\nPremium проверяет цены каждый час, поэтому вы быстрее узнаёте о скидках и изменениях стоимости.\n\n🔔 <b>Индивидуальные уведомления</b>\n\nДля каждой игры можно настроить целевую цену, минимальную скидку, заметное снижение стоимости и правила повторных уведомлений.\n\n🌙 <b>Тихие часы</b>\n\nВ выбранный период бот не беспокоит сообщениями. Все события сохраняются и автоматически отправляются после окончания тихих часов.\n\n📬 <b>Ежедневные и еженедельные дайджесты</b>\n\nПолучайте аккуратную сводку важных скидок, минимумов, изменений цен и бесплатных раздач за день или неделю. Пустые сводки не отправляются.\n\n━━━━━━━━━━━━━━━━━━\nPremium даёт больше информации и контроля над отслеживаемыми играми, помогая оценивать покупку по полной картине изменения цены.",
    "en": "⭐️ <b>More possibilities with Premium</b>\n\nPremium turns DealDock into a complete price-analysis tool, helping you spot worthwhile offers sooner and see more useful information about every game.\n\n📊 <b>Advanced price analytics</b>\n\n• current, lowest and highest observed prices\n• average price and changes between checks\n• purchase-value assessment\n• difference between the current price and the low\n• detailed price-change history\n\n🏆 <b>Lows and worthwhile offers</b>\n\nFollow new lows, repeated returns to the best observed price and genuinely interesting buying moments.\n\n🌍 <b>Regional price comparison</b>\n\nChoose regions, compare a game's price and convert values into one currency to identify the most attractive option more easily.\n\n⚡️ <b>More frequent checks</b>\n\nPremium checks prices every hour, so you learn about discounts and price changes sooner.\n\n🔔 <b>Individual alert settings</b>\n\nFor each game, configure a target price, minimum discount, meaningful price drop and repeat-alert rules.\n\n🌙 <b>Quiet hours</b>\n\nThe bot stays silent during your chosen period. Events are stored and delivered automatically when quiet hours end.\n\n📬 <b>Daily and weekly digests</b>\n\nReceive a tidy summary of important discounts, lows, price changes and giveaways for the day or week. Empty summaries are not sent.\n\n━━━━━━━━━━━━━━━━━━\nPremium provides more information and control over tracked games, helping you assess a purchase using the full picture of price changes.",
    "uk": "⭐️ <b>Більше можливостей із Premium</b>\n\nPremium перетворює DealDock на повноцінний інструмент аналізу цін: допомагає швидше помічати цікаві пропозиції та бачити більше корисної інформації про кожну гру.\n\n📊 <b>Розширена аналітика цін</b>\n\n• поточна, мінімальна й максимальна ціна за період\n• середня вартість і зміни між перевірками\n• оцінка вигідності покупки\n• різниця між поточною ціною та мінімумом\n• докладна історія зміни вартості\n\n🏆 <b>Мінімуми та вигідні пропозиції</b>\n\nСтежте за новими мінімумами, повторним досягненням найкращої ціни та справді цікавими моментами для покупки.\n\n🌍 <b>Порівняння регіональних цін</b>\n\nВиберіть потрібні регіони, порівняйте вартість гри та приведіть ціни до однієї валюти, щоб швидше побачити найвигідніший варіант.\n\n⚡️ <b>Частіші перевірки</b>\n\nPremium перевіряє ціни щогодини, тому ви швидше дізнаєтеся про знижки та зміни вартості.\n\n🔔 <b>Індивідуальні сповіщення</b>\n\nДля кожної гри можна налаштувати цільову ціну, мінімальну знижку, помітне зниження вартості та правила повторних сповіщень.\n\n🌙 <b>Тихі години</b>\n\nУ вибраний період бот не турбує повідомленнями. Усі події зберігаються й автоматично надсилаються після завершення тихих годин.\n\n📬 <b>Щоденні та щотижневі дайджести</b>\n\nОтримуйте охайну добірку важливих знижок, мінімумів, змін цін і безкоштовних роздач за день або тиждень. Порожні дайджести не надсилаються.\n\n━━━━━━━━━━━━━━━━━━\nPremium дає більше інформації та контролю над відстежуваними іграми й допомагає оцінювати покупку за повною картиною зміни ціни.",
    "pl": "⭐️ <b>Więcej możliwości z Premium</b>\n\nPremium zmienia DealDock w pełne narzędzie do analizy cen, które pomaga szybciej zauważać interesujące oferty i poznawać więcej przydatnych informacji o każdej grze.\n\n📊 <b>Rozszerzona analiza cen</b>\n\n• bieżąca, minimalna i maksymalna cena z okresu obserwacji\n• średnia cena i zmiany między sprawdzeniami\n• ocena opłacalności zakupu\n• różnica między bieżącą ceną a minimum\n• szczegółowa historia zmian ceny\n\n🏆 <b>Minima i opłacalne oferty</b>\n\nObserwuj nowe minima, ponowne osiągnięcie najlepszej ceny oraz naprawdę interesujące momenty na zakup.\n\n🌍 <b>Porównanie cen regionalnych</b>\n\nWybierz regiony, porównaj cenę gry i przelicz wartości na jedną walutę, aby łatwiej znaleźć najkorzystniejszą opcję.\n\n⚡️ <b>Częstsze sprawdzanie</b>\n\nPremium sprawdza ceny co godzinę, dzięki czemu szybciej dowiadujesz się o promocjach i zmianach kosztu.\n\n🔔 <b>Indywidualne ustawienia alertów</b>\n\nDla każdej gry ustaw cenę docelową, minimalny rabat, istotny spadek ceny oraz zasady ponawiania powiadomień.\n\n🌙 <b>Ciche godziny</b>\n\nBot nie przeszkadza w wybranym okresie. Wszystkie zdarzenia są zapisywane i automatycznie wysyłane po zakończeniu ciszy.\n\n📬 <b>Podsumowania dzienne i tygodniowe</b>\n\nOtrzymuj czytelne zestawienie ważnych promocji, minimów, zmian cen i darmowych rozdań z dnia lub tygodnia. Puste podsumowania nie są wysyłane.\n\n━━━━━━━━━━━━━━━━━━\nPremium zapewnia więcej informacji i kontroli nad obserwowanymi grami, pomagając ocenić zakup na podstawie pełnego obrazu zmian ceny.",
}
for _locale, _value in _PREMIUM_INFO_27.items():
    _UI27[_locale]["premium_full_info"] = _value

