def text(locale: str | None, key: str, **kwargs: object) -> str:
    language = locale if locale in TEXTS else "ru"
    template = TEXTS[language].get(key) or TEXTS["ru"].get(key) or TEXTS["ru"]["ui_error"]
    return template.format(**kwargs)
